create function private.cleanup_delivery_quotes() returns integer language plpgsql security definer set search_path='' as $$ declare n integer; begin delete from private.delivery_quotes where order_id is null and status<>'used' and expires_at<now()-interval '2 days' and not exists(select 1 from private.order_deliveries d where d.quote_id=delivery_quotes.id); get diagnostics n=row_count; return n; end; $$; revoke all on function private.cleanup_delivery_quotes() from public,anon,authenticated; select cron.schedule('cubica-cleanup-delivery-quotes','15 6 * * *','select private.cleanup_delivery_quotes()');

